public class Foo {
    public void finalize() {
        super.finalize();
    }
}

public class Foo {
    public void finalize() {
        int x = 2;
        super.finalize();
    }
}

class OneBlock {
    protected void finalize() throws Throwable {
        { super.finalize(); }
    }
    void cleanup() { }
}

class ManyBlocks {
    protected void finalize() throws Throwable {
        { { { super.finalize(); } } }
    }
    void cleanup() { }
}

class CleanupFirst {
    protected void finalize() throws Throwable {
        cleanup();
        { super.finalize(); }
    }
    void cleanup() { }
}

class WorkInsideBlock {
    protected void finalize() throws Throwable {
        { cleanup(); super.finalize(); }
    }
    void cleanup() { }
}

class Conditional {
    boolean enabled;
    protected void finalize() throws Throwable {
        if (enabled) { super.finalize(); }
    }
}

class OtherMethod {
    void dispose() throws Throwable {
        { super.finalize(); }
    }
}

class TryFinally {
    protected void finalize() throws Throwable {
        try { cleanup(); } finally { super.finalize(); }
    }
    void cleanup() { }
}

class Base { }
class Outer extends Base {
    class Inner extends Base {
        protected void finalize() throws Throwable {
            { Outer.super.finalize(); }
        }
    }
}

class Base { }
class Outer extends Base {
    class Inner extends Base {
        protected void finalize() throws Throwable {
            Outer.super.finalize();
        }
    }
}
